"""Self-Contained Kaggle Runner for NoxQuantum Day 3 Cascade Benchmark.

Packs the entire nox library and benchmarks inline (36 KB base64 bundle).
Executes 4-Layer Cascade (Layers 15 -> 18) under both Extreme (77x) and Production (18x) tiers
on free NVIDIA T4 GPU compute with zero cloud costs and zero external git dependencies.
"""

import os
import io
import base64
import tarfile
import subprocess
import sys

BUNDLE_B64 = ""

def unpack_bundle():
    print("[Kaggle Runner] Unpacking NoxQuantum codebase from inline bundle...", flush=True)
    raw = base64.b64decode(BUNDLE_B64)
    tar = tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")
    tar.extractall(".")
    tar.close()
    print("[Kaggle Runner] Unpacked nox/ and benchmarks/ successfully.", flush=True)

def run_cmd(cmd):
    print("[Kaggle Runner] Executing:", cmd, flush=True)
    res = subprocess.run(cmd, shell=True, text=True)
    if res.returncode != 0:
        print("[Kaggle Runner] Warning: Command returned non-zero exit code", res.returncode, flush=True)
    return res.returncode

def main():
    unpack_bundle()

    import torch
    if torch.cuda.is_available():
        print("[Kaggle Runner] GPU Active:", torch.cuda.get_device_name(0), flush=True)
    else:
        print("[Kaggle Runner] Running on CPU", flush=True)

    div = "=" * 90
    print(flush=True)
    print(div, flush=True)
    print(" EXECUTING TIER 1: EXTREME STRESS-TEST (77x COMPRESSION, ~5.1 MB/LAYER)", flush=True)
    print(div, flush=True)
    run_cmd("python3 benchmarks/benchmark_day3_cascade.py --start_layer 15 --end_layer 18 --tier extreme_77x")

    print(flush=True)
    print(div, flush=True)
    print(" EXECUTING TIER 2: PRODUCTION COMPACTIFAI-KILLER (18x COMPRESSION, ~20 MB/LAYER)", flush=True)
    print(div, flush=True)
    run_cmd("python3 benchmarks/benchmark_day3_cascade.py --start_layer 15 --end_layer 18 --tier production_18x")

    print("[Kaggle Runner] Day 3 Cascade benchmarks completed.", flush=True)

if __name__ == "__main__":
    main()
